begin;
create extension if not exists pgtap with schema extensions;
select plan(22);

-- Tokens: 64 hex chars generated by the server; only hashes are stored.
\set tok_a '''aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'''
\set tok_b '''bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'''

select tests.login_anon();

select is((public.cart_get(:tok_a) ->> 'item_count')::int, 0, 'unknown token yields an empty cart, never an error');
select throws_ok($$select public.cart_add_item('not-a-token', '20000000-0000-4000-8000-000000000011', 1)$$, 'P0001', null, 'malformed tokens are rejected');
select throws_ok($$select public.cart_add_item('aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa', '20000000-0000-4000-8000-000000000099', 1)$$, 'P0001', null, 'draft product variants cannot be added');
select throws_ok($$select public.cart_add_item('aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa', '20000000-0000-4000-8000-000000000011', 0)$$, 'P0001', null, 'quantity must be >= 1');
select throws_ok($$select public.cart_add_item('aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa', '20000000-0000-4000-8000-000000000022', 5)$$, 'P0001', null, 'cannot add more than available stock');
select throws_ok($$select public.cart_add_item('aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa', '20000000-0000-4000-8000-000000000031', 1, '[{"add_on_id":"f0000000-0000-4000-8000-000000000004","quantity":1}]')$$, 'P0001', null, 'add-ons not configured for the product are rejected');

-- Happy path ---------------------------------------------------------------
select is(
  (public.cart_add_item(:tok_a, '20000000-0000-4000-8000-000000000011', 2, '[{"add_on_id":"f0000000-0000-4000-8000-000000000001","quantity":1}]') ->> 'total_centavos')::int,
  249000 * 2 + 5000, 'totals are computed server-side from live prices');
select is((public.cart_get(:tok_a) -> 'items' -> 0 ->> 'quantity')::int, 2, 'line persisted');
select is((public.cart_add_item(:tok_a, '20000000-0000-4000-8000-000000000011', 1) -> 'items' -> 0 ->> 'quantity')::int, 3, 'adding the same variant merges quantities');
select is((public.cart_get(:tok_a) ->> 'item_count')::int, 3, 'item_count sums quantities');
select is((public.cart_get(:tok_b) ->> 'item_count')::int, 0, 'another token cannot see this cart');

-- Anon has no direct table access: everything must go through the RPCs.
select throws_ok($$select count(*) from public.carts$$, '42501', null, 'anon cannot read carts directly');
select throws_ok($$select count(*) from public.cart_items$$, '42501', null, 'anon cannot read cart_items directly');

-- Update / remove ------------------------------------------------------------
select public.cart_get(:tok_a) -> 'items' -> 0 ->> 'id' as item_id \gset
select is((public.cart_update_item(:tok_a, :'item_id', 1) -> 'items' -> 0 ->> 'quantity')::int, 1, 'quantity can be updated');
select throws_ok(format($$select public.cart_update_item('bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb', %L, 1)$$, :'item_id'), 'P0001', null, 'another token cannot update the item');
select is((public.cart_update_item(:tok_a, :'item_id', 0) ->> 'item_count')::int, 0, 'quantity 0 removes the line');

-- Price revalidation ---------------------------------------------------------
select public.cart_add_item(:tok_a, '20000000-0000-4000-8000-000000000003', 1);
select tests.logout();
update public.product_variants set price_centavos = 70000 where id = '20000000-0000-4000-8000-000000000003';
select tests.login_anon();
select is((public.cart_get(:tok_a) -> 'items' -> 0 ->> 'price_changed')::boolean, true, 'price changes since add are flagged');
select is((public.cart_get(:tok_a) -> 'items' -> 0 ->> 'unit_price_centavos')::int, 70000, 'live price is returned, not the price at add');
select is((public.cart_get(:tok_a) ->> 'has_issues')::boolean, true, 'cart reports issues');
select is((public.cart_remove_unavailable(:tok_a) ->> 'has_issues')::boolean, false, 'acknowledging re-prices the line');

-- Unavailable product --------------------------------------------------------
select tests.logout();
update public.products set status = 'archived' where id = '10000000-0000-4000-8000-000000000002';
select tests.login_anon();
select is((public.cart_get(:tok_a) -> 'items' -> 0 ->> 'is_available')::boolean, false, 'archived products are flagged unavailable');
select is((public.cart_remove_unavailable(:tok_a) ->> 'item_count')::int, 0, 'unavailable lines can be dropped in one call');

select tests.logout();
select * from finish();
rollback;
